export type CountryCode = 'RO' | 'MD' | 'GR' | 'CY' | 'RS' | 'ME' | 'BG' | 'MK' | 'UA' | 'GE' | 'RU' | 'BY' | 'AL';
export const SUPPORTED_LANGUAGES = ['ro', 'en', 'el', 'sr', 'bg', 'mk', 'uk', 'ka', 'ru', 'sq'] as const;
export type LanguageCode = typeof SUPPORTED_LANGUAGES[number];
export const COMPLETE_LANGUAGES = ['ro', 'en', 'el', 'sr', 'bg', 'mk', 'uk', 'ka', 'ru', 'sq'] as const;
export type CompleteLanguageCode = typeof COMPLETE_LANGUAGES[number];

export function isSupportedLanguage(code: string): code is LanguageCode {
  return (SUPPORTED_LANGUAGES as readonly string[]).includes(code);
}

export function resolveLanguageCode(code: string | null | undefined): LanguageCode {
  return code && isSupportedLanguage(code) ? code : 'ro';
}
export type CalendarCode = 'ro-bor' | 'md-basarabia' | 'md-chisinau' | 'gr-church-of-greece' | 'cy-church-of-cyprus' | 'rs-serbian-orthodox-church' | 'me-metropolitanate-montenegro-littoral' | 'ua-orthodox-church-of-ukraine' | 'bg-bulgarian-patriarchate' | 'mk-macedonian-orthodox-church' | 'ge-georgian-orthodox-church' | 'ru-russian-orthodox-church' | 'by-belarusian-orthodox-church' | 'al-orthodox-autocephalous-church';

export type RegionConfig = {
  countryCode: CountryCode;
  countryLabel: string;
  currencyCode: 'RON' | 'MDL' | 'EUR' | 'RSD' | 'MKD' | 'UAH' | 'GEL' | 'RUB' | 'BYN' | 'ALL';
  languageCode: LanguageCode;
  languageLabel: string;
  locale: 'ro-RO' | 'ro-MD' | 'el-GR' | 'el-CY' | 'sr-RS' | 'sr-ME' | 'bg-BG' | 'mk-MK' | 'uk-UA' | 'ka-GE' | 'ru-RU' | 'ru-BY' | 'sq-AL';
  timeZone: 'Europe/Bucharest' | 'Europe/Chisinau' | 'Europe/Athens' | 'Asia/Nicosia' | 'Europe/Belgrade' | 'Europe/Podgorica' | 'Europe/Sofia' | 'Europe/Skopje' | 'Europe/Kyiv' | 'Asia/Tbilisi' | 'Europe/Moscow' | 'Europe/Minsk' | 'Europe/Tirane';
};

export type CalendarConfig = {
  calendarCode: CalendarCode;
  countryCode: CountryCode;
  description: string;
  jurisdictionLabel: string;
  label: string;
  officialUrl: string;
};

