  'terms.s1Content': 'Use of the Ortodoxia application is conditional upon acceptance of these terms. If you do not agree, please do not use the application.',
  'terms.s2Title': '2. Eligibility',
  'terms.s2Content': 'The application is intended for people who meet the minimum age required to create an account on the Apple App Store / Google Play platforms. Minors must use the application with the consent of their legal representative.',
  'terms.s3Title': '3. Your account',
  'terms.s3Content1': 'You are responsible for keeping your account credentials confidential and for all activities carried out through your account. Notify us immediately at the support address if you suspect unauthorized use.',
