  'terms.s5Li4': '• circumventing usage restriction mechanisms (e.g. the daily AI message limit);',
  'terms.s5Li5': '• deliberately entering content that may generate harmful or unlawful responses.',
  'terms.s6Title': '6. Limitations of AI content',
  'terms.s6Intro': 'AI Chat responses are generated automatically by a language model. They:',
  'terms.s6Li1': '• may contain errors or inaccuracies;',
  'terms.s6Li2': '• must be independently assessed by the user;',
  'terms.s6Li3': '• do not represent the official views of the Orthodox Church or any ecclesiastical authority.',
  'terms.s6_1Title': '6.1 AI does not replace professionals',
  'terms.s6_1Intro': 'AI Chat does not replace or act as a substitute for:',
  'terms.s6_1Li1': '• a priest or spiritual father — for spiritual guidance;',
  'terms.s6_1Li2': '• a doctor — for diagnosis, treatment, or medical advice;',
  'terms.s6_1Li3': '• a lawyer — for legal advice;',
  'terms.s6_1Li4': '• an emergency service.',
  'terms.s6_1Content': 'For medical, psychological, or safety emergencies, contact the emergency services immediately (112 in Romania, or the appropriate number in your country).',
  'terms.s6_2Title': '6.2 Limitations regarding religious content',
  'terms.s6_2Content1': 'Religious explanations generated by AI are not official ecclesiastical rulings. For doctrinal, canonical, or liturgical matters, consult official Church sources (Holy Scripture, the writings of the Holy Fathers, and your spiritual father’s guidance).',
  'terms.s6_2Content2': 'The application does not imply or claim the endorsement or support of any Church authority.',
  'terms.s6_3Title': '6.3 Your responsibility',
  'terms.s6_3Content': 'You are solely responsible for decisions made on the basis of AI-generated information. Do not rely exclusively on these responses for important decisions concerning your health, spiritual life, rights, or safety.',
  'terms.s7Title': '7. External content',
  'terms.s7Content': 'The application may display live broadcasts, links, or editorial quotations from third parties. These remain the responsibility of their respective providers. Ortodoxia does not guarantee the accuracy, availability, or currency of external content.',
  'terms.s8Title': '8. Subscriptions',
  'terms.s8Content': 'Premium features are available through a monthly or annual subscription. The subscription renews automatically until cancelled.',
  'terms.s8_1Title': '8.1 Payments and renewal',
  'terms.s8_1Content': 'Payments are processed by Apple App Store or Google Play. Automatic renewal is cancelled through your account on the respective platform (Settings → Subscriptions).',
  'terms.s8_2Title': '8.2 Cancellation',
  'terms.s8_2Content': 'Cancellation stops future renewal. Access to Premium features remains active until the end of the period already paid for.',
  'terms.s8_3Title': '8.3 Uninstallation',
  'terms.s8_3Content': 'Uninstalling the application does not cancel the subscription. Cancellation is only handled through App Store / Google Play.',
  'terms.s8_4Title': '8.4 Refunds',
