  'layout.privacyTitle': 'Privacy Policy',
  'privacy.title': 'Privacy Policy',
  'privacy.meta': 'Version: 1.0 — [DATA DE COMPLETAT]',
  'privacy.s1Title': '1. Controller',
  'privacy.s1Entity': '[OPERATOR/ENTITATE LEGALĂ DE COMPLETAT]',
  'privacy.s1Support': '[ADRESĂ DE SUPORT DE COMPLETAT]',
  'privacy.s1Postal': '[ADRESĂ POȘTALĂ DE COMPLETAT]',
  'privacy.s2Title': '2. What data we collect',
  'privacy.s2Intro': 'Ortodoxia processes the following data categories, strictly to the extent that the application’s functionalities use them.',
  'privacy.s2_1Title': '2.1 Authentication data',
  'privacy.s2_1Content': 'When creating an account, we collect the provided email address and password. The password is stored hashed (not in plaintext) by Supabase.',
  'privacy.s2_2Title': '2.2 User profile',
  'privacy.s2_2Content': 'The user-set display name is stored in the `profiles` table in Supabase, associated with the unique account identifier.',
  'privacy.s2_3Title': '2.3 Region and calendar preferences',
  'privacy.s2_3Content': 'The region and liturgical calendar preference is stored locally on the device and is not automatically transmitted to the server.',
  'privacy.s2_4Title': '2.4 AI conversations',
  'privacy.s2_4Content1': 'When an authenticated user sends a message to the AI Chat, the content of messages and responses is stored in the `chat_threads` and `chat_messages` tables in Supabase, associated with the account.',
  'privacy.s2_4Content2': 'Daily usage of AI messages is recorded in the `usage_daily` table. For unauthenticated users, a locally generated identifier is used; usage is recorded in `guest_usage_daily`.',
  'privacy.s2_4Content3': 'Do not enter sensitive personal information in AI conversations. Messages reflect what you voluntarily provide.',
  'privacy.s2_5Title': '2.5 Notification preferences',
  'privacy.s2_5Content': 'If you enable notifications, the preference state is stored in the `notification_preferences` table. An Expo Push Token is transmitted and stored server-side. The token is regenerated by the Expo system and does not contain personal data.',
  'privacy.s2_6Title': '2.6 Subscriptions and payments',
  'privacy.s2_6Content': 'Payments are managed by Apple App Store, Google Play, and RevenueCat. Subscription status is synchronized via a server-side webhook and stored in the `subscriptions` table in Supabase. We do not store bank card data.',
  'privacy.s2_7Title': '2.7 Prayers and preferences',
  'privacy.s2_7Content': 'Prayers are stored in the `prayers` table in Supabase. Saved favorites are stored in the `favorites` table associated with the account.',
  'privacy.s2_8Title': '2.8 AI-generated audio content',
  'privacy.s2_8Content': 'Upon request, the application can generate audio for a prayer using OpenAI text-to-speech. The resulting file is stored in Supabase Storage. Generation takes place on the server.',
  'privacy.s2_9Title': '2.9 LIVE services status',
  'privacy.s2_9Content': 'The "LIVE Services" page displays the live status of selected video sources. Verification is performed on the server using the YouTube Data API and is temporarily cached in the `live_service_status_cache` table. No personal data is collected in connection with the use of this function.',
  'privacy.s2_10Title': '2.10 Error logs',
  'privacy.s2_10Content': 'In case of connection errors, certain logs may contain information about the failed request. These logs do not deliberately contain personal data and are not used for analysis or tracking purposes.',
